window.__saqPaperQuestions("2023-1-northern-sydney",[{"number":1,"title":"","stemText":"A 50-year-old female patient presents to the emergency department after a 50 km/hr motor vehicle collision (MVC). She self-extricated from the vehicle and complains of right-sided chest pain exacerbated by movement, bruising on the right side of her abdomen, neck pain and stiffness, and a swollen, painful left ankle that she cannot bear weight on. Her vital signs are as follows: Heart rate: 130 bpm Oxygen saturation: 98% on room air Respiratory rate: 12 breaths/min after receiving 10 mg of IV morphine from paramedics Blood pressure: 130/80 mmHg She is using methoxyflurane for pain relief but still reports 5/10 pain, predominantly in her ankle.","parts":[{"id":"a","label":"Part A","prompt":"State one (1) rare side effect from methoxyflurane use (1 mark)"},{"id":"b","label":"Part B","prompt":"Complete the table with one (1) liver injury which would satisfy the definition of each of the corresponding liver injury grades (4 marks)"},{"id":"c","label":"Part C","prompt":"List three (3) abnormalities in these x-rays (3 marks)"},{"id":"d","label":"Part D","prompt":"She has ongoing severe pain in the left ankle and you elect to perform procedural sedation with ketamine. Outline your approach to procedural sedation for this patient (4 marks)"},{"id":"e","label":"Part E","prompt":"During procedural sedation with ketamine she develops laryngospasm. Outline your step-by-step approach to managing this situation (6 marks)"}],"propPages":["asset:imge3a888e3bdefc613fe","asset:img70dfc74550ef618609"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Malignant hyperthermia</div><div class=\"answer-line\">CT trauma series shows right sided rib fractures from 3-6 as well as a very small</div><div class=\"answer-line\">pneumothorax. She also has a grade 2 liver laceration with no active blush. Her</div><div class=\"answer-line\">respiratory status remains unchanged, with no oxygen requirement. Her HR has</div><div class=\"answer-line\">reduced to 105 and her Hb is 132 with a normal lactate.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">*(There is an actual table on the site)*</td></tr><tr><td></td><td><strong>grade I (filled in already)</strong></td></tr><tr><td colspan=\"2\">haematoma: subcapsular, &lt;10% surface area</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">laceration: capsular tear, &lt;1 cm  parenchymal depth</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td><strong>grade II</strong></td></tr><tr><td colspan=\"2\">haematoma: subcapsular, 10-50% surface area</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">haematoma: intraparenchymal &lt;10 cm diameter</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">laceration: capsular tear 1-3 cm parenchymal depth, &lt;10 cm length</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td><strong>grade III</strong></td></tr><tr><td colspan=\"2\">haematoma: subcapsular, &gt;50% surface area of ruptured</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">subcapsular or parenchymal haematoma</td></tr><tr><td colspan=\"2\">haematoma: intraparenchymal &gt;10 cm</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">laceration: capsular tear &gt;3 cm parenchymal depth</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">vascular injury with active bleeding contained within liver</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">parenchyma</td></tr><tr><td></td><td><strong>grade IV</strong></td></tr><tr><td colspan=\"2\">laceration: parenchymal disruption involving 25-75% hepatic lobe</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">or involves 1-3 Couinaud segments</td></tr><tr><td colspan=\"2\">vascular injury with active bleeding breaching the liver parenchyma</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">into the peritoneum</td></tr><tr><td></td><td><strong>grade V</strong></td></tr><tr><td colspan=\"2\">laceration: parenchymal disruption involving &gt;75% of hepatic lobe</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">vascular: juxtahepatic venous injuries (retrohepatic vena cava /</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">central major hepatic veins)</td></tr><tr><td colspan=\"2\">X-rays of her left ankle have also been performed, see below.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Subtalar dislocation</em></div><div class=\"answer-line\"><em>Distal fibular fracture</em></div><div class=\"answer-line\"><em>Widening of tibiotalar joint laterally</em></div><div class=\"answer-line\">She has ongoing severe pain in the left ankle and you elect to perform procedural</div><div class=\"answer-line\">sedation with ketamine.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Proceed with caution given her other injuries</div><div class=\"answer-line\">ICC not required at this stage, however should be considered in the event the</div><div class=\"answer-line\">patient deteriorates from a respiratory perspective</div><div class=\"answer-line\">Non-rebreather on and airway plan prepared with team made aware of potential</div><div class=\"answer-line\">for deterioration</div><div class=\"answer-line\">Ensure patient has an active group and screen</div><div class=\"answer-line\">IV fluids on a pump set with pre-procedure IV bolus 10ml/kg crystalloid</div><div class=\"answer-line\">Metaraminol drawn up</div><div class=\"answer-line\">During procedural sedation with ketamine she develops laryngospasm.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Abort procedure</div><div class=\"answer-line\">Airway opening manoeuvres</div><div class=\"answer-line\">Pressure over Larson’s point</div><div class=\"answer-line\">Suction as required</div><div class=\"answer-line\">Apply PEEP via BVM with 100% FiO2</div><div class=\"answer-line\">Assisted ventilation</div><div class=\"answer-line\">Deepen sedation – propofol</div><div class=\"answer-line\">RSI</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 21-year-old male patient presents to the emergency department 10 days after undergoing an uncomplicated tonsillectomy. He reports bleeding from the site of the surgery. The patient has no relevant past medical history.\n\nVital signs:\n- Heart rate: 115 bpm - Blood pressure: 100/60 mmHg - Oxygen saturation: 92% on room air - Respiratory rate: 25 breaths/min - Temperature: 37.5°C - Weight: 110 kg","parts":[{"id":"a","label":"Part A","prompt":"List five (5) treatment options that can be employed in the emergency department to help control the bleeding in this patient. (5 marks)"},{"id":"b","label":"Part B","prompt":"Provide a step-by-step approach for managing this patient's worsening condition. (7 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">hydrogen peroxide (3%) gargles</td></tr><tr><td>-</td><td>co-phenylcaine spray</td></tr><tr><td>-</td><td>1:10000 adrenaline soaked gauze pads</td></tr><tr><td>-</td><td>nebulised adrenaline 5mg in 5 ml</td></tr><tr><td>-</td><td>TXA soaked gauze</td></tr><tr><td>-</td><td>cauterize with silver nitrate</td></tr><tr><td>-</td><td>1:100000 local adrenaline injection if clear bleeding point</td></tr><tr><td colspan=\"2\">Despite implementing the suggested interventions, the bleeding continues, and the</td></tr><tr><td colspan=\"2\">patient&#x27;s condition deteriorates. He becomes hemodynamically unstable and</td></tr><tr><td colspan=\"2\">demonstrates signs of a compromised airway. The ENT registrar is 45 minutes away,</td></tr><tr><td colspan=\"2\">and the anesthesic team is also experiencing delays.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">optimise patient prior to intubation :</td></tr><tr><td>-</td><td>Patient position – obese patient, try ramping</td></tr><tr><td>-</td><td>Airway - Adequate suction 2 x wide bore yanked suckers</td></tr><tr><td>-</td><td>pre oxygenation or apnoea oxygen sensible options</td></tr><tr><td>-</td><td>Direct laryngoscope vs video (can be problematic as obscure views so need to</td></tr><tr><td colspan=\"2\">recognise this)</td></tr><tr><td>-</td><td>Haemodynamics:  support and optimisation Blood/ metaraminol /etc</td></tr><tr><td>-</td><td>RSI agents: say something sensible e.g. ketamine to avoid hypotension and</td></tr><tr><td colspan=\"2\">Roc</td></tr><tr><td>-</td><td>Most experienced operator</td></tr><tr><td>-</td><td>Comment on attempts to manage bleeding post intubation with direct</td></tr><tr><td colspan=\"2\">pressure/adrenaline</td></tr><tr><td>-</td><td>further interventions: ENT/ surgery/IR/correct any coagulopathy</td></tr><tr><td>-</td><td>Disposition ICU</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 40-year-old man presents following a reaction to seafood. He developed flushing of his face and neck and some chest tightness within a minute of eating tuna he had bought at a local organic produce market.\nHis vital signs\n\nHR 112\n\nBP 105/55\n\nSats 100% on air\nAfebrile You suspect scombroid poisoning.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) non-cutaneous clinical manifestations of scombroid poisoning (4 marks)"},{"id":"b","label":"Part B","prompt":"List three (3) investigations that can help differentiate scombroid poisoning from IgE-mediated anaphylaxis, and briefly explain your rationale. (6 marks)"},{"id":"c","label":"Part C","prompt":"Bloods for IgE specific to the fish +/- IgE for anasakis (a fish parasite) List two (2) significant non-marine differential diagnoses for this patient, other than anaphylaxis. Additionally, list two (2) examples of marine poisonings that could be considered in this case. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">marks)</td></tr><tr><td></td><td>Abdo cramps, n, v, d</td></tr><tr><td></td><td>Headache</td></tr><tr><td></td><td>Tachycardia, palpitations, hypotension</td></tr><tr><td></td><td>Bronchospasm, resp distress</td></tr><tr><td colspan=\"2\">Peppery, metallic taste to the fish flesh</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Send sample of the fish (or possibly of vomitus) for examination for histamine</td></tr><tr><td colspan=\"2\">levels. If elevated confirms scrombroid</td></tr><tr><td></td><td>Bloods for IgE specific to the fish +/- IgE for anasakis (a fish parasite)</td></tr><tr><td></td><td>Skin prick testing – challenge to the fish in question</td></tr><tr><td></td><td>Mast cell tryptase – useful to confirm anaphylaxis if positive – less useful as a</td></tr><tr><td colspan=\"2\">“rule out”. Not usually useful in ingested allergens (versus bites/stings)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>than</strong> anaphylaxis. <strong>Additionally</strong>, list two (2) examples of marine poisonings that could</td></tr><tr><td colspan=\"2\">be considered in this case. (4 marks)</td></tr><tr><td></td><td>Myocardial ischaemia – chest tightness, tachy/hypotensive</td></tr><tr><td></td><td>PE</td></tr><tr><td></td><td>Food poisoning – e.g. Staph enterotoxin – abrupt n, v, cramps</td></tr><tr><td colspan=\"2\">Other marine poisoning – ciguatera, pufferfish, neurotoxic shellfish</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"An 84-year-old gentleman has been brought in via ambulance from his nursing home. He has presented following a syncope. His ECG is shown below.","parts":[{"id":"a","label":"Part A","prompt":"Interpret this ECG (2 marks)"},{"id":"b","label":"Part B","prompt":"List five (5) different classes of medication which can cause these ECG findings, and for each class, list an example medication (10 marks)"},{"id":"c","label":"Part C","prompt":"State the diagnosis (1 mark)"},{"id":"d","label":"Part D","prompt":"He is now alert and his observations are within normal limits. Outline five (5) steps in your management of this patient (5 marks)"}],"propPages":["asset:img1debe46050536e77cc","asset:img4b3b3d424b3a3cd1d6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">An 84-year-old gentleman has been brought in via ambulance from his nursing</div><div class=\"answer-line\">home. He has presented following a syncope. His ECG is shown below.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td><em>Antibiotics – macrolides (clarithromycin)</em></td><td><em>Antipsychotics – haloperidol, quetiapine, olanzepine</em></td></tr><tr><td><em>Antiemetics – metoclopramide, ondansetron</em></td><td><em>Antiarrhythmics – Quinidine, Flecanide, Sotalol, Amiodarone</em></td></tr><tr><td><em>Antidepressants – Amitryptiline, escitalopram, citalopram</em></td><td><em>Antihistamines - Loratidine</em></td></tr><tr><td>The monitor alarm goes off while his nurse is attending to him. He had a brief</td><td>episode of being unresponsive. A further ECG is captured, see below.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Torsades de Pointes / Polymorphic VT</em></div><div class=\"answer-line\">He is now alert and his observations are within normal limits.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em>Keep monitored – in resus ideally. Full cardiac monitoring with defib pads on – </em></div><div class=\"answer-line\"><em>prepare to defibrillate if pulseless / cardiovert if unstable</em></div><div class=\"answer-line\"><em>Cease all offending drugs</em></div><div class=\"answer-line\"><em>Load with Magnesium as likely cause due to prolonged QT – 2grams IV MgSO4 over </em></div><div class=\"answer-line\"><em>10-20 minutes unless unstable – can be pushes</em></div><div class=\"answer-line\"><em>Start infusion at 1-4 grams / hr</em></div><div class=\"answer-line\"><em>Monitor magnesium levels, if &gt;2.5mmol/L cut infusion in half, if &gt;3mmol/L stop </em></div><div class=\"answer-line\"><em>infusion</em></div><div class=\"answer-line\"><em>Monitor clinically – monitor reflexes, bradycardia, respiratory distress (side effect is </em></div><div class=\"answer-line\"><em>depression of neuromuscular function) – prepare to intubate if this occurs</em></div><div class=\"answer-line\"><em>Optimise electroltyes – specifically potassium and calcium</em></div><div class=\"answer-line\"><em>Review the pacemaker settings and consult with a cardiologist to evaluate whether </em></div><div class=\"answer-line\"><em>the pacemaker settings can be adjusted to shorten the QT interval and/or increase </em></div><div class=\"answer-line\"><em>the pacing rate to prevent recurrent episodes of Torsades de Pointes.</em></div><div class=\"answer-line\"><em>Isoprenaline is another option to increase the HR and therefore decrease QT – aim </em></div><div class=\"answer-line\"><em>30bpm above natural rate.</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 47-year-old male presents to a rural ED with facial / mouth pain. The pain is unilateral over his left cheek. It is intermittent and he notices it mainly with eating. The patient has also noted unilateral facial swelling when he has the pain which is what prompted the visit to emergency. He is otherwise well, with no fevers and vitals all within normal ranges. He has no relevant past medical history. He is currently symptom free and examination is normal.","parts":[{"id":"a","label":"Part A","prompt":"State the most likely diagnosis and outline the discharge instructions you would give this patient (3 marks)"},{"id":"d","label":"Part D","prompt":"The patient is sent home. Several weeks later he returns to ED with severe persistent unilateral facial pain, swelling and fevers. He is currently febrile to 39.6, PR 120, BP 90/60, RR 32, Saturations 94% Room air. He is showing several signs of potential airway compromise. List four (4) signs on examination that would indicate a potential imminent airway obstruction (4 marks)"},{"id":"e","label":"Part E","prompt":"Outline your management of this patient (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["1 mark for sialolithiasis,","1 mark for analgesia, 1 mark for massage or 1 mark for monitor for signs of infection (max 3 marks total)","1 mark for each line above. Max 5 marks"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Likely simple sialolithiasis (salivary calculi). Treat with simple analgesia. Can</div><div class=\"answer-line\">discuss massage and explain self-massage technique to patient. Monitor for signs</div><div class=\"answer-line\">of infection and seek medical attention if develops any. Can do US to confirm if</div><div class=\"answer-line\">any concerns.</div><div class=\"answer-line\">1 mark for sialolithiasis,</div><div class=\"answer-line\">1 mark for analgesia, 1 mark for massage or 1 mark for monitor for signs of</div><div class=\"answer-line\">infection (max 3 marks total)</div><div class=\"answer-line\">The patient is sent home. Several weeks later he returns to ED with severe persistent</div><div class=\"answer-line\">unilateral facial pain, swelling and fevers. He is currently febrile to 39.6, PR 120, BP</div><div class=\"answer-line\">90/60, RR 32, Saturations 94% Room air. He is showing several signs of potential</div><div class=\"answer-line\">airway compromise.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Can’t protrude tongue, trismus, drooling, stridor, obstructs airway with neck flexion</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Move to resuscitation room. Keep patient sitting upright as per their comfort.</div><div class=\"answer-line\">Call nearest ENT specialist, Likely no ENT specialist available on site in rural ED.</div><div class=\"answer-line\">Prepare for urgent intubation – may not be needed or may be able to delay until</div><div class=\"answer-line\">backup arrives. Aim for awake fibreoptic with OT backup is the preference if required</div><div class=\"answer-line\">which may not be possible in rural ED. May request help from anaesthetics if</div><div class=\"answer-line\">available</div><div class=\"answer-line\">Nebulised adrenaline temporising measure if needed</div><div class=\"answer-line\">Give IV AB – clindamycin, or benzylpenicillin + metronidazole or other appropriate</div><div class=\"answer-line\">choice.</div><div class=\"answer-line\">Dexamethasone IV 8-10mg</div><div class=\"answer-line\">CT scan if able to tolerate but not absolutely necessary. Check if patient can tolerate</div><div class=\"answer-line\">lying flat for scan. Gently start to lay flat and if any issues sit back up.</div><div class=\"answer-line\">Will need transfer to centre with ENT, will need ICU/HDU</div><div class=\"answer-line\">1 mark for each line above. Max 5 marks</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"You are the ED consultant in a rural hospital. A 31-year-old male presents to ED with vertigo and blurred vision. About 6 hours ago he was trying some of the alcohol he distilled in a home set up. He initially had vomiting and abdominal pain which subsequently resolved. You perform bloods including a VBG, which is displayed below. Additional lab results show urea of 9, ethanol level of 0 and measured serum osmolality of 322 mOsmol/L.","parts":[{"id":"a","label":"Part A","prompt":"Analyse and interpret these results, showing your calculations (4 marks)"},{"id":"b","label":"Part B","prompt":"State the antidote for this toxidrome that is used in Australia, along with the dosing regimen. (2 marks)"},{"id":"c","label":"Part C","prompt":"List four (4) indications for dialysis in the context of this toxidrome (4 marks)"},{"id":"d","label":"Part D","prompt":"List two (2) potential long-term complications of this toxidrome (2 marks)"}],"propPages":["asset:img9b66100c1675f64607"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">HAGMA - (140 – (100 + 12)) = 28</div><div class=\"answer-line\">Adequate respiratory compensation - pCO2 expected: (1.5 X 12) + 8 = 26 +/- 2</div><div class=\"answer-line\">Calculated osmolarity: (2 x sodium 140) + urea (9) + glucose (3) + ethanol (0)</div><div class=\"answer-line\">= 292</div><div class=\"answer-line\">Osmolar gap: 322 – 292 = 30</div><div class=\"answer-line\">Consistent with toxic alcohol ingestion – methanol</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Antidote: Ethanol</div><div class=\"answer-line\">Dosing regmine: Oral / NG Loading - 1.8ml/kg of 43% ethanol or 3 x 40ml</div><div class=\"answer-line\">shots of vodka in a 70kg adult (omit of ethanol level already raised).</div><div class=\"answer-line\">Maintenance – 0.2-0.4ml/kg/hr of 43% or 40ml shot each hour.</div><div class=\"answer-line\">IV – Loading – 8ml/kg  of 10% ethanol. Maintenance 1-2ml/kg/hr of 10%</div><div class=\"answer-line\">(probably easier to remember)</div><div class=\"answer-line\">End point is blood ethanol level 100-150 mg/dL</div><div class=\"answer-line\">c.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Any patient who you are treating with ethanol</div><div class=\"answer-line\">pH &lt;7.3</div><div class=\"answer-line\">Visual symptoms</div><div class=\"answer-line\">Renal failure</div><div class=\"answer-line\">Deterioration of vital signs or electrolyte status despite supportive care</div><div class=\"answer-line\">Methanol level &gt;16 mmol/L (50mg/dL)</div><div class=\"answer-line\">Osmolar gap &gt;10</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Blindness (up to a third of patients)</div><div class=\"answer-line\">Extrapyramidal movement disorders</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 28-year-old female is brought to your rural ED after dousing herself with accelerant, then setting herself on fire. She has extensive burns. Paramedics have given her 60mg IM ketamine, however she is still screaming in pain. They have been unable to establish IV access.","parts":[{"id":"a","label":"Part A","prompt":"Outline the differentiating clinical features of superficial, partial and full thickness burns (3 marks)"},{"id":"b","label":"Part B","prompt":"Outline six (6) steps in your management of this patient (6 marks)"},{"id":"c","label":"Part C","prompt":"Other than stridor, list four (4) indications for urgent RSI in the context of burns (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Superficial: Epidermis only, No blisters, Red/pink, painful, Normal CRT</div><div class=\"answer-line\">Partial: Epidermis/dermis, blisters, Red, moist, painful, Normal CRT</div><div class=\"answer-line\">Full: Epidermis/dermis/subC tissue, No blisters, Pearl/charred, leathery,</div><div class=\"answer-line\">Insensate, No bleeding</div><div class=\"answer-line\">On your assessment you find:</div><div class=\"answer-line\">A – Soft stridor</div><div class=\"answer-line\">B – Restricted chest wall movement, RR 22, sats 99% on 10L Hudson mask</div><div class=\"answer-line\">C – HR 115, BP 110/80, strong radial pulses, hands slightly cool.</div><div class=\"answer-line\">D – GCS 15, PEARL</div><div class=\"answer-line\">E – partial or full thickness burns to the entire head and face, entire anterior and</div><div class=\"answer-line\">posterior trunk including the buttocks, the entire left leg. The arms and right leg have</div><div class=\"answer-line\">only small patches of superficial burns. Pulses in the left foot are absent and no cap</div><div class=\"answer-line\">refill in the toes.</div><div class=\"answer-line\">Temp 35.3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">IV/IO access</div><div class=\"answer-line\"><strong>Analgesia – any appropriate</strong></div><div class=\"answer-line\"><strong>RSI – ideally in OT / awake fibreoptic, otherwise VL with anaesthetic support</strong></div><div class=\"answer-line\"><strong>Chest and left leg escharotomies</strong></div><div class=\"answer-line\">Fluid resuscitation and ongoing fluids as per Parkland – on a fluid warmer</div><div class=\"answer-line\">Warm patient – any reasonable strategy aiming temp &gt;36</div><div class=\"answer-line\">Make preparations for retrieval to tertiary burns centre</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Other than stridor</strong>, list four (4) indications for urgent RSI in the context of</div><div class=\"answer-line\">burns (4 marks)</div><div class=\"answer-line\">Hypoxia on high flow O2 via facial mask</div><div class=\"answer-line\">Significant hypoventilation/decr LOC</div><div class=\"answer-line\">Voice change; oral erythema/blistering; neck swelling; wheeze; brassy cough</div><div class=\"answer-line\">Circumferential neck burns</div><div class=\"answer-line\">Supraglottic oedema, soot or inflammation on bronchoscopy</div><div class=\"answer-line\">Full thickness burns face or perioral region</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 14-year-old girl, with known anorexia nervosa, is sent in by her GP due to concerns about recent weight loss.\nShe weighs 36 kg and is 160 cm tall with a BMI of 14.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) clinical criteria of medical instability that warrant admission in the context of eating disorders (4 marks)"},{"id":"b","label":"Part B","prompt":"The patient is refusing to be weighed, have an ECG or blood tests. Her parents are present. Outline your step-by-step approach to managing this situation. (4 Marks)"},{"id":"c","label":"Part C","prompt":"Any 4 of the following , 0 marks if they mention sending home without investigation"},{"id":"d","label":"Part D","prompt":"She probably does not have mental capacity due to poor nutrition affecting cognition and immaturity The patient hates being admitted and suddenly asks to eat a full meal. List four (4) clinical features of the refeeding syndrome (4 marks)"}],"propPages":["asset:img5701ec7673e2e6618a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Severe recent </em></div><div class=\"answer-line\"><em>weight loss &gt;= 1kg for several weeks</em></div><div class=\"answer-line\"><em>BMI&lt;14 (&lt;16 for psych and possible medical &lt;14 for medical ie need to go to </em></div><div class=\"answer-line\"><em>medical not psych ward)</em></div><div class=\"answer-line\"><em>Bradycardia &lt; 40 tachycardia &gt;110, </em></div><div class=\"answer-line\"><em>Hypotension &lt;80 postural drop &gt;20</em></div><div class=\"answer-line\"><em>ECG abnormality including QT prolongation and t wave abnormalities</em></div><div class=\"answer-line\"><em>Electrolyte abnormalities especially hypokalaemia</em></div><div class=\"answer-line\"><em>Temp &lt;35 or extremities cold and blue</em></div><div class=\"answer-line\"><em>Severe weakness- unable to walk</em></div><div class=\"answer-line\"><em>Abnormal LFTs</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">She weighs 36 kg and is 160 cm tall with a BMI of 14.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>1. The child is a minor and the wishes of her legal guardians (parents) can </em></div><div class=\"answer-line\"><em>override her wishes</em></div><div class=\"answer-line\"><em>2. She probably does not have mental capacity due to poor nutrition affecting </em></div><div class=\"answer-line\"><em>cognition and immaturity</em></div><div class=\"answer-line\"><em>3. Making the parents allies in achieving investigations</em></div><div class=\"answer-line\"><em>4. Negotiation</em></div><div class=\"answer-line\"><em>5. De-escalation</em></div><div class=\"answer-line\"><em>6. Use of mental health act as a person who is mentally disordered ie delusional</em></div><div class=\"answer-line\"><em>7. As last resort –sedation</em></div><div class=\"answer-line\"><em>8. Threat of physical restraint</em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">c.</div><div class=\"answer-line\">List four (4) clinical features of the refeeding syndrome (4 marks)</div><div class=\"answer-line\"><em>Definition (from up to date)The refeeding syndrome is defined as the clinical </em></div><div class=\"answer-line\"><em>complications that can occur as a result of fluid and electrolyte shifts during </em></div><div class=\"answer-line\"><em>aggressive nutritional rehabilitation of malnourished patients [8]. These </em></div><div class=\"answer-line\"><em>complications are potentially fatal when not detected or treated early during </em></div><div class=\"answer-line\"><em>nutritional rehabilitation.</em></div><div class=\"answer-line\"><em>●Hypophosphatemia</em></div><div class=\"answer-line\"><em>●Hypokalemia</em></div><div class=\"answer-line\"><em>●Congestive heart failure</em></div><div class=\"answer-line\"><em>●Peripheral edema</em></div><div class=\"answer-line\"><em>●Rhabdomyolysis</em></div><div class=\"answer-line\"><em>●Seizures</em></div><div class=\"answer-line\"><em>●Hemolysis</em></div><div class=\"answer-line\"><em>●Respiratory insufficiency</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"One of your registrars has questions about methods of oxygenating hypoxic patients and organises some one-on-one teaching time with you.","parts":[{"id":"a","label":"Part A","prompt":"What is the function of the valves/ports labelled 1, 2 and 3 in this image of a non-rebreather mask? (6 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table noting the typical FiO2 provided by various oxygen delivery devices (3 marks)"},{"id":"c","label":"Part C","prompt":"Other than the ability to supply a high FiO2, outline two mechanisms by which HFNC improves oxygenation? (4 marks)"},{"id":"d","label":"Part D","prompt":"List three (3) commonly accepted indications for HFNC in adults (3 marks)"}],"propPages":["asset:imgfb9eda5d4fac5d6eae"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(1) One-way valve separates the reservoir bag from the mask. Oxygen (from</div><div class=\"answer-line\">wall/tank) flows into the reservoir – when the patient inhalesO2 comes from</div><div class=\"answer-line\">the reservoir. On exhalation, the valve closes preventing exhaled gases</div><div class=\"answer-line\">entering the reservoir.</div><div class=\"answer-line\">(2) One-way valve on the side of the mask keeps air being entrained into mask</div><div class=\"answer-line\">during inhalation. On exhalation gas leaves mask thru this port and the port</div><div class=\"answer-line\">labelled 3.</div><div class=\"answer-line\">(3) Exhalation port with no valve. This functions as a safety feature – if 1 and 2</div><div class=\"answer-line\">are both occluded (or if 2 is occluded and 1 has no incoming O2 supply) no</div><div class=\"answer-line\">gas could enter the mask except thru 3 (discounting imperfect seal around</div><div class=\"answer-line\">face)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Device</td><td>Typical FiO2 range</td></tr><tr><td>“Normal” nasal cannulae</td><td>24-40%</td></tr><tr><td>Simple face mask (“Hudson”)</td><td>40-60%</td></tr><tr><td>Non-rebreather mask</td><td>60-90%</td></tr><tr><td colspan=\"2\">High-flow humidified nasal cannula (HFNC) oxygen delivery is frequently used in</td></tr><tr><td colspan=\"2\">hypoxic respiratory failure.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Other than</strong> the ability to supply a high FiO2, outline two mechanisms by</div><div class=\"answer-line\">which HFNC improves oxygenation? (4 marks)</div><div class=\"answer-line\">Pharyngeal dead space washout. Upper airway/pharyngeal dead space is about 150</div><div class=\"answer-line\">mL (25% of TV) The high-flow jet of O2 washes this out to some extent – forms an O2</div><div class=\"answer-line\">reservoir and avoids inhalation of stale, CO2-rich dead space gas</div><div class=\"answer-line\">PEEP effect. Probably 3 cm H2O (at 60 L/min) with mouth open versus 7-8 with</div><div class=\"answer-line\">mouth closed  recruitment of atelectatic lungs, improvement in O2 delivery in</div><div class=\"answer-line\">setting of alveolar filling issues (like APO, ARDS)</div><div class=\"answer-line\">Oxygen dilution reduction. Patients with respiratory failure have high inspiratory</div><div class=\"answer-line\">flow rates (they’re breathing hard &amp; fast) maybe up to 60 - 120l/min. With normal</div><div class=\"answer-line\">O2 flow rates, lots++ of air is entrained, diluting the O2 (and so the FiO2) by a</div><div class=\"answer-line\">variable and sometimes large amount. HFNC rates usually exceed the patient’s</div><div class=\"answer-line\">inspiratory flow rate and little room air is entrained…i.e. the high flow rates match</div><div class=\"answer-line\">the patient’s inspiratory demand</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Hypoxic respiratory failure (mostly from CAP – also pneumonitis)</div><div class=\"answer-line\">Post-extubation resp distress</div><div class=\"answer-line\">Pre-oxygenation/apnoeic oxygenation peri-intubation</div><div class=\"answer-line\">Treatment of resp failure in setting of DNI order</div><div class=\"answer-line\">?CCF/APO</div><div class=\"answer-line\">Acute severe asthma</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 65-year-old woman with a cardiac transplant presents to your ED with worsening shortness of breath on exertion. An ECG is performed:","parts":[{"id":"a","label":"Part A","prompt":"Explain the appearances of the P waves in this ECG (2 marks)"},{"id":"b","label":"Part B","prompt":"Complete the following table (4 marks)"},{"id":"c","label":"Part C","prompt":"List three (3) clinical features that occur in the setting of acute rejection of the transplanted heart (3 marks)"},{"id":"d","label":"Part D","prompt":"What are the typical clinical and ECG findings suggestive of myocardial ischaemia in the transplanted heart? (3 marks)"}],"propPages":["asset:img9eef2a68d2763df0ba"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">12 lead EKG shows <strong>accessory atrial activity (better seen in lead II) due to some of </strong></div><div class=\"answer-line\"><strong>the original sinus node still remaining in addition to the donor sinus node</strong> after a</div><div class=\"answer-line\">cardiac transplant. Because of a suture line in the right atrium <strong>the ectopic atrial </strong></div><div class=\"answer-line\"><strong>rhythm rarely conducts to the AV node</strong></div><div class=\"answer-line\">Transplanted hearts have altered physiology and responses to pharmacological</div><div class=\"answer-line\">agents.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Transplanted Heart</td></tr><tr><td>Normal resting heart rate</td><td>90 ( to 100) bpm</td></tr><tr><td>Response to adrenaline infusion</td><td>Preserved/normal response - tachycardia</td></tr><tr><td>Response to atropine use in</td><td>No effect at all b/c denervation</td></tr><tr><td colspan=\"2\">bradycardia</td></tr><tr><td>Response to adenosine in SVT</td><td>Increased/sensitive</td></tr><tr><td colspan=\"2\">c.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Generalised fatigue</td></tr><tr><td></td><td>Myocardial/pump dysfunction  CCF  progressive failure/circulatory</td></tr><tr><td colspan=\"2\">collapse</td></tr><tr><td></td><td>Fever</td></tr><tr><td></td><td>Majority are asymptomatic</td></tr><tr><td colspan=\"2\">Accelerated atherosclerosis of graft coronary arteries is common.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Denervated heart does not present with angina</td></tr><tr><td></td><td>Typically present with heart failure symptoms/signs from silent infarction –</td></tr><tr><td colspan=\"2\">SOB, SOBOE, fatigue</td></tr><tr><td></td><td>Dysrhythmias +/- sudden death</td></tr><tr><td colspan=\"2\">ECG should show the usual changes of ischaemia</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 65-year-old regular cocaine user presents with chest discomfort and an episode of pre-syncope.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) mechanisms by which cocaine use predisposes to chest pain, cardiac ischaemia and/or dysrhythmias (5 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table indicating three (3) medications you would use to manage chest pain in the setting of cocaine intoxication (doses not required) (6 marks)"},{"id":"c","label":"Part C","prompt":"Explain what this means (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Sodium channel blockade</td></tr><tr><td></td><td>Sympathetic/adrenergic excess – increased myocardial O2 demand</td></tr><tr><td></td><td>Coronary vasospasm</td></tr><tr><td></td><td>Accelerated atherosclerosis</td></tr><tr><td></td><td>Hypercoagulable state</td></tr><tr><td></td><td>Direct myocardial toxicity</td></tr><tr><td></td><td>Myocarditis/endocarditis</td></tr><tr><td></td><td>Aortic dissection</td></tr><tr><td colspan=\"2\">Takotsubo’s</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">manage chest pain in the setting of cocaine intoxication (doses not required)</td></tr><tr><td colspan=\"2\">(6 marks)</td></tr><tr><td>Drug</td><td>Rationale</td></tr><tr><td>Aspirin</td><td>Antiplatelet action</td></tr><tr><td>Nitrates</td><td>Reduce vasospasm</td></tr><tr><td>Diazepam (other benzo)</td><td>Reduce sympathetic surge, reduce</td></tr><tr><td colspan=\"2\">HR/BP O2 demand</td></tr><tr><td>Phentolamine</td><td>Direct alpha-antagonist – reduce O2</td></tr><tr><td colspan=\"2\">demand etc</td></tr><tr><td>Verapamil/Diltiazem</td><td>Slow HR, reduce O2 demand etc</td></tr><tr><td>Labetalol</td><td>As above</td></tr><tr><td colspan=\"2\">While controversial, beta-blockers are traditionally said to be contraindicated</td></tr><tr><td colspan=\"2\">because they can lead to “unopposed alpha stimulation”.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Cocaine and other sympathomimetics cause an increase in</td></tr><tr><td></td><td>Alpha</td><td>-activity leading to vasoconstriction and an increase in BP</td></tr><tr><td></td><td>Beta-1</td><td>- activity leading to an increase in HR and contractility and an increase</td></tr><tr><td colspan=\"3\">in BP</td></tr><tr><td></td><td>Beta-2</td><td>-activity which causes</td></tr><tr><td>o</td><td>Bronchodilation</td><td></td></tr><tr><td><em>o</em></td><td><em>Vasodilation</em></td><td><em> </em> in some vascular beds (e.g. muscles) <em>partially opposing </em></td></tr><tr><td colspan=\"3\"><em>the alpha-mediated vasoconstriction</em></td></tr><tr><td colspan=\"3\">Giving a beta-blocker stops this partial off-setting of vasoconstriction and</td></tr><tr><td colspan=\"3\">“unopposed alpha stimulation”</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 6-day-old is brought to your ED, floppy and lethargic. The child was born at term by normal vaginal delivery. Birth weight 2900g. He was discharged on Day 2 of life and is being formula fed. He has had progressive lethargy and worsening feeding over 2-3 days In the ED: Pale\n\nRR 60\n\nHR 170, poor cap refill\nFloppy, withdraws & cries with painful stimulus Sepsis and congenital cardiac abnormalities are common causes of the “crashing neonate”.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) other differentials in five (5) different categories (5 marks)"},{"id":"b","label":"Part B","prompt":"Outline your initial empiric treatment steps for this child in the first hour (5 marks)"},{"id":"c","label":"Part C","prompt":"Explain the pharmacodynamics of prostaglandin E1 infusions in this context (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Trauma – birth-related injury, NAI</td></tr><tr><td></td><td>Endocrine e.g. CAH</td></tr><tr><td></td><td>Metabolic / Inborn Errors of Metabolism – resulting in lactic acidosis,</td></tr><tr><td colspan=\"2\">hypoglycaemia, hyperammonaemia</td></tr><tr><td></td><td>Formula-related – too concentrated or too dilute  Na and osm</td></tr><tr><td colspan=\"2\">abnormalities</td></tr><tr><td></td><td>Intestinal disasters – volvulus, necrotising enterocolitis</td></tr><tr><td></td><td>Toxins –maternal drugs if BF (e.g. codeine), home remedies</td></tr><tr><td></td><td>Seizures</td></tr><tr><td colspan=\"2\">“THE MISFITS”</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">marks)</td></tr><tr><td></td><td>IV/IO/umb vein access  VBG, BSL, BCs (metabolic screen also includes</td></tr><tr><td colspan=\"2\">ketones, lactate, ammonia)</td></tr><tr><td></td><td>If BSL low  Glucose 10% 5mL/kg</td></tr><tr><td></td><td>NS 10mL/kg bolus</td></tr><tr><td></td><td>Empiric antibiotics amp + cefotaxime or gent</td></tr><tr><td></td><td>Consider CAH – hydrocortisone 2mg/kg</td></tr><tr><td></td><td>Consider PGE1</td></tr><tr><td colspan=\"2\">Based on your examination findings, you suspect a duct dependent abnormality like</td></tr><tr><td colspan=\"2\">coarctation of the aorta.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Explain the pharmacodynamics of prostaglandin E1 infusions in this context</div><div class=\"answer-line\">(2 marks)</div><div class=\"answer-line\">In the setting of left heart outflow obstruction (coarctation, severe AS), a</div><div class=\"answer-line\"></div><div class=\"answer-line\">patent ductus arteriosis supplies systemic blood flow. As the ductus closes (in</div><div class=\"answer-line\">the majority of term neonates within 1st few days of life), systemic flow</div><div class=\"answer-line\">reduces. The ductus is kept open in utero by high concentration of PGE1 from</div><div class=\"answer-line\">placenta. Giving an infusion of PGE1 keeps it open or re-opens it</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 70-year-old female is brought in acutely confused. She is normally independent in her ADLs but has been becoming more dependent on her family in recent months.","parts":[{"id":"a","label":"Part A","prompt":"List the five (5) categories used in the mini mental state examination (5 marks)"},{"id":"b","label":"Part B","prompt":"Other than infection, list four (4) common causes of acute confusion in an adult (4 marks)"},{"id":"c","label":"Part C","prompt":"List six (6) features on history or examination that would suggest an organic rather than a psychiatric cause of confusion (6 marks)"}],"propPages":["asset:img020b31fee5f890b32d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Orientation</em></div><div class=\"answer-line\"><em>Registration</em></div><div class=\"answer-line\"><em>Attention and Calculation</em></div><div class=\"answer-line\"><em>Recall</em></div><div class=\"answer-line\"><em>Language</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\"><em>Drugs – opiates, anticonvulsants, L-Dopa, sedatives, recreational</em></div><div class=\"answer-line\"><em>Alcohol/drug withdrawal</em></div><div class=\"answer-line\"><em>Metabolic – hypoglycaemia, ureamia, liver failure, electrolyte imbalance</em></div><div class=\"answer-line\"><em>Hypoxia – respiratory or cardiac failure</em></div><div class=\"answer-line\"><em>Vascular – stroke, MI</em></div><div class=\"answer-line\"><em>Raised ICP – SOL</em></div><div class=\"answer-line\"><em>Epilepsy – status epilepticus, post-ictal states</em></div><div class=\"answer-line\"><em>Head injury – esp. SDH</em></div><div class=\"answer-line\"><em>Nutritional  - thiamine, nicotinic acid, B12</em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List six (6) features on history or examination that would suggest an organic rather</div><div class=\"answer-line\">than a psychiatric cause of confusion (6 marks)</div><div class=\"answer-line\"><em><strong>Physical / mental state exam</strong></em></div><div class=\"answer-line\"><em>Signs of infection – fever, source of sepsis</em></div><div class=\"answer-line\"><em>Fluctuating level of awareness</em></div><div class=\"answer-line\"><em>Visual hallucinations (auditory hallucinations more indicative of a psychiatric illness, 15%  </em></div><div class=\"answer-line\"><em>schizophrenics will experience visual hallucinations but in addition to auditory hallucinations)</em></div><div class=\"answer-line\"><em>Focal neurological signs</em></div><div class=\"answer-line\"><em>Seizures</em></div><div class=\"answer-line\"><em>Abnormal vital signs inc glucose</em></div><div class=\"answer-line\"><em>Retinal haemorrhages</em></div><div class=\"answer-line\"><em>Pale, swollen optic disc</em></div><div class=\"answer-line\"><em>History of trauma/HI</em></div><div class=\"answer-line\"><em>Dysarthria</em></div><div class=\"answer-line\"><em>Ataxia</em></div><div class=\"answer-line\"><em>Gait disturbance</em></div><div class=\"answer-line\"><em>Incontinence</em></div><div class=\"answer-line\"><em><strong>Historical features</strong></em></div><div class=\"answer-line\"><em>No history of psychiatric illness</em></div><div class=\"answer-line\"><em>Older age &gt;40</em></div><div class=\"answer-line\"><em>Onset over hours – days</em></div><div class=\"answer-line\"><em>Complaint of headache</em></div><div class=\"answer-line\"><em>Any new medication</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"25-year-old female presents with a widespread rash after starting penicillin V a week ago for a sore throat.","parts":[{"id":"a","label":"Part A","prompt":"Describe this rash (2 marks)"},{"id":"b","label":"Part B","prompt":"List five (5) other causes of this rash. (5 marks)"},{"id":"c","label":"Part C","prompt":"On closer examination of the patient you discover that she has mucosal involvement. Your resident asks you whether this could be Stevens-Johnson Syndrome (SJS)/Toxic Epidermal Necrolysis (TEN). Outline how SJS and TEN are classified and differentiated. (3 marks)"},{"id":"d","label":"Part D","prompt":"List your management priorities when treating SJS/TENS (4 marks)"},{"id":"e","label":"Part E","prompt":"List four (4) complications of SJS/TENS (4 marks)"}],"propPages":["asset:imged34333c2bd37a0a18"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>-</em><em> Multiple irregular target lesions of varying size </em></div><div class=\"answer-line\"><em>-</em><em> Larger area of more confluent erythema on the right inner thigh</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>-</em><em> HSV</em></div><div class=\"answer-line\"><em>-</em><em> other drugs: phenytoin, carbamazepine , cephalosporins, omeprazole, NSAIDs</em></div><div class=\"answer-line\"><em>-</em><em> mycoplasma pneumonia</em></div><div class=\"answer-line\"><em>-</em><em> CMV</em></div><div class=\"answer-line\"><em>-</em><em> EBV</em></div><div class=\"answer-line\"><em>-</em><em> adenovirus </em></div><div class=\"answer-line\"><em>-</em><em> HIV</em></div><div class=\"answer-line\"><em>-</em><em> influenza </em></div><div class=\"answer-line\"><em>-</em><em> cancer</em></div><div class=\"answer-line\">On closer examination of the patient you discover that she has mucosal involvement. Your</div><div class=\"answer-line\">resident asks you whether this could be Stevens-Johnson Syndrome (SJS)/Toxic Epidermal</div><div class=\"answer-line\">Necrolysis (TEN).</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>-</em><em> Based on the skin surface area detached at maximal extent</em></div><div class=\"answer-line\"><em>-</em><em> SJS &lt;10% BSA</em></div><div class=\"answer-line\"><em>-</em><em> (overlap 10-30% BSA)</em></div><div class=\"answer-line\"><em>-</em><em> TENs detachment &gt;30% BSA with spots or &gt;10% without spots</em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em>-</em><em> Specific: stop offending agent, treatment with IVIG +/- ciclospiron/infliximab, </em></div><div class=\"answer-line\"><em>plasmapheresis (must avoid steroids) </em></div><div class=\"answer-line\"><em>-</em><em> Skin care:  dressings, mouthwashes, catheter</em></div><div class=\"answer-line\"><em>-</em><em> Fluid therapy: IVF </em></div><div class=\"answer-line\"><em>-</em><em> Disposition : burns unit. </em></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><em>-</em><em> infection/sepsis: skin, mucous membranes, lungs</em></div><div class=\"answer-line\"><em>-</em><em> ARDS</em></div><div class=\"answer-line\"><em>-</em><em> GI ulceration , perforation, intussusception</em></div><div class=\"answer-line\"><em>-</em><em> Shock and MOF </em></div><div class=\"answer-line\"><em>-</em><em> DIC/VTE</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 59-year-old patient is found unconscious in their home after a welfare check was performed. He is hypotensive with a GCS of 5:","parts":[{"id":"a","label":"Part A","prompt":"Describe the ECG (3 mark)"},{"id":"b","label":"Part B","prompt":"Other than hypothermia, list two (2) conditions associated with the QRS abnormality seen in this ECG. (2 Marks)"},{"id":"c","label":"Part C","prompt":"Excluding environmental exposure, medications and toxins, list four (4) medical conditions that can cause hypothermia (4 Marks)"},{"id":"d","label":"Part D","prompt":"In the setting of hypothermic arrest, detail how you would carry out closed thoracic lavage as an invasive rewarming technique (4 marks)"}],"propPages":["asset:imga7901fad06a4bd6dde"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Junctional brady, elevated J point, Osborn wave. Widened QRS, widespread ST/T changes (3</div><div class=\"answer-line\">marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Subarachnoid haemorrhage, traumatic brain injury, hypercalcaemia, Brugada syndrome,</div><div class=\"answer-line\">early repolarisation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Mild</td><td>32-35 degrees Celsius</td></tr><tr><td>Moderate</td><td>28-32</td></tr><tr><td>Severe</td><td>&lt;28</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">hypothyroidism; adrenal insufficiency; hypopituitarism; sepsis; neuromuscular disease</div><div class=\"answer-line\">(spinal cord injury, MS); malnutrition (eating disorder); thiamine deficiency; hypoglycaemia;</div><div class=\"answer-line\">skin disorder such as burns or exfoliative dermatitis, cardiopulmonary bypass; massive</div><div class=\"answer-line\">transfusion</div><div class=\"answer-line\">e. In the setting of hypothermic arrest, detail how you would carry out closed thoracic</div><div class=\"answer-line\">lavage as an invasive rewarming technique (4 marks)</div><div class=\"answer-line\">Two thoracostomy tubes  - ideally one supero-anterio and the other baso-lateral. Tube one</div><div class=\"answer-line\">continuously infused with bags NS heated to 40-41C and drainage collected in a drain</div><div class=\"answer-line\">bag/device. Alternative is a single ICC and  200-300 mL aliquots  with a 2 min dwell time,</div><div class=\"answer-line\">drain , repeat</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"An 81-year-old lady with a background of dementia is brought in by ambulance from her nursing home. She was found face down and unresponsive. She had been seen that morning walking in the hallway. Her usual GCS is 14 - confused. Upon arrival to ED:\n\nGCS 8 - E1, V2, M5\n\nSats 95% on 15L O2\n\nHR 95bpm\n\nBP 140/80\nOn examination she had obvious bruising and swelling to the right side of her face and a laceration to the right eyebrow. Nil other obvious injuries. There appeared to be proptosis of her right eye with a relative afferent pupillary defect. Her CT facial bones is shown below:","parts":[{"id":"a","label":"Part A","prompt":"List three (3) abnormalities in the CT scans above (3 marks)"},{"id":"b","label":"Part B","prompt":"List three (3) indications for a lateral canthotomy (3 marks)"},{"id":"c","label":"Part C","prompt":"Describe how to perform a lateral canthotomy (6 marks)"},{"id":"d","label":"Part D","prompt":"Her CTB also shows subarachnoid and intraventricular haemorrhage. The distribution and pattern are worrisome for diffuse axonal injury. She deteriorates further. She is now a GCS 5 and just appears to be moaning in pain. You note there is a clear NFR in her nursing home notes but with the wrong patient name on these documents. What would your immediate management plan be? (4 marks)"}],"propPages":["asset:img97df26f18eb0cb58d6","asset:imgc11700615482170c1b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Proptosis of right orbit</em></div><div class=\"answer-line\"><em>Gas retrobulbar space right orbit</em></div><div class=\"answer-line\"><em>Orbital floor fracture</em></div><div class=\"answer-line\"><em>Lateral left maxillary wall – with gas associated </em></div><div class=\"answer-line\"><em>Concern about potential Le Fort / blow out fracture</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Decreased visual acuity</em></div><div class=\"answer-line\"><em>Intraocular pressure &gt;40mmHg</em></div><div class=\"answer-line\"><em>Proptosis</em></div><div class=\"answer-line\"><em>Afferent pupillary defect</em></div><div class=\"answer-line\"><em>Cherry red macula</em></div><div class=\"answer-line\"><em>Opthalmoplegia</em></div><div class=\"answer-line\"><em>Nerve head pallor</em></div><div class=\"answer-line\"><em>Eye pain</em></div><div class=\"answer-line\">c.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Use local anaesthetic but warn patient that they may feel pain – can use local anaesthetic – </em></div><div class=\"answer-line\"><em>inject from lateral canthus to orbital rim.</em></div><div class=\"answer-line\"><em>Slide a straight mosquito hemostat along the lateral canthus, with one prong against the </em></div><div class=\"answer-line\"><em>orbit and the other superficial to the skin. Compress this tissue for 1 minute </em></div><div class=\"answer-line\"><em>Perform the canthotomy – place scissors across the lateral canthus and incise the canthus </em></div><div class=\"answer-line\"><em>full thickness</em></div><div class=\"answer-line\"><em>Perform the cantholysis – grasp the lower eyelip with toothed forceps. Pull eyelid anteriorly. </em></div><div class=\"answer-line\"><em>Point scissors towards patient’s nose, place the blades either side of the lateral canthal </em></div><div class=\"answer-line\"><em>tendon and cut</em></div><div class=\"answer-line\"><em>Bonus question not included in the exam</em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">notes but with the wrong patient name on these documents. What would your immediate</div><div class=\"answer-line\">management plan be? (4 marks)</div><div class=\"answer-line\"><em>Need to contact NOK and nursing home staff – alert them of wrong patient ID and attempt </em></div><div class=\"answer-line\"><em>to clarify patient and families wishes</em></div><div class=\"answer-line\"><em>Unlikely to do very well from injuries – emphasis on comfort care</em></div><div class=\"answer-line\"><em>Can discuss with neurosurgical team but unlikely surgical candidate</em></div><div class=\"answer-line\"><em>Reverse any blood thinners to prevent further bleed</em></div><div class=\"answer-line\"><em>Analgesia and palliate</em></div><div class=\"answer-line\"><em>If candidate does intubate – need aim and end point to this</em></div><div class=\"answer-line\"><em>Intubate and ventilate preventing secondary brain injuries</em></div><div class=\"answer-line\"><em>Neurosurg consult</em></div><div class=\"answer-line\"><em>ICU involvement</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 2-week-old neonate is brought to your outer urban district hospital ED by his mother with a 8-hour-long history of distress and several episodes of “yellow-green vomit”. He looks floppy, pale and lethargic. You are most concerned about intestinal malrotation with midgut volvulus.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) other important causes of bilious vomiting in a neonate (5 marks)"},{"id":"b","label":"Part B","prompt":"Discuss the imaging modalities available to evaluate for midgut volvulus (3 marks)"},{"id":"c","label":"Part C","prompt":"Outline your immediate management priorities (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Intestinal atresia (duod/jej-ileal/colon)</td></tr><tr><td>●</td><td>Meconium ileus</td></tr><tr><td>●</td><td>Necrotising enterocolitis</td></tr><tr><td>●</td><td>Intestinal perforation</td></tr><tr><td>●</td><td>Hirschsprungs</td></tr><tr><td>●</td><td>Anorectal malformation</td></tr><tr><td>●</td><td>Septic ileus</td></tr><tr><td>●</td><td>GORD</td></tr><tr><td>●</td><td>Gastric dysmotility</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">AXR - rarely helpful. Frequently normal or non-diagnostic. May have mild dilation,</td></tr><tr><td colspan=\"2\">gasless abdomen, double-bubble sign</td></tr><tr><td>●</td><td>USS - often used as an initial screening tool - if diagnostic → laparotomy. If not</td></tr><tr><td colspan=\"2\">diagnostic need contrast imaging</td></tr><tr><td>●</td><td>Upper GI contrast series - with contrast swallow</td></tr><tr><td>●</td><td>Abdo CT - less sens/spec than upper GI series</td></tr><tr><td colspan=\"2\">c.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">IV access/check sugar/fluid resuscitation</td></tr><tr><td>●</td><td>IV antibiotics to cover intra-abdominal source +/- empiric sepsis cover</td></tr><tr><td>●</td><td>Urgent surgical involvement - if Dx confirmed needs urgent laparotomy</td></tr><tr><td>●</td><td>Early contact with neonatal transport service - likely to need urgent TF to tertiary</td></tr><tr><td colspan=\"2\">paeds</td></tr><tr><td>●</td><td>Looking after the parents</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 12-month-old child weighing 10kg is arriving in your ED in cardiac arrest. The child was previously well and has no known medical conditions.","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table: (5 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) potential benefits of intubation in cardiac arrest. (4 marks)"},{"id":"c","label":"Part C","prompt":"List three (3) methods to confirm successful endotracheal intubation. (3 marks)"},{"id":"d","label":"Part D","prompt":"Outline four (4) actions you are responsible for as medical team leader. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Cuffed ETT size</td><td>3.5</td></tr><tr><td>Normal saline bolus (mL)</td><td>100-200mL</td></tr><tr><td>Adrenaline dose (micrograms)</td><td>100 microg</td></tr><tr><td>10% Glucose dose (mL)</td><td>20mL</td></tr><tr><td>Joules for DCCV (pulseless shockable rhythm)</td><td>40J</td></tr><tr><td colspan=\"2\">You decide to intubate the child.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>establishes and maintains a patent airway</td></tr><tr><td></td><td>facilitates initial mechanical ventilation with 100% oxygen (and later accurate</td></tr><tr><td colspan=\"2\">administration of lesser amounts)</td></tr><tr><td></td><td>minimises pulmonary aspiration and pulmonary oedema</td></tr><tr><td></td><td>enables suctioning of the trachea</td></tr><tr><td></td><td>safer &amp; more practical than BVM ventilation during prolonged management or</td></tr><tr><td colspan=\"2\">transport (airway protection, ventilation)</td></tr><tr><td colspan=\"2\">c.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>the tip of the tube is visualised passing through the vocal cords at intubation</td></tr><tr><td></td><td>bilateral lung inflation on auscultation of breath sounds in the axillae</td></tr><tr><td></td><td>observation of intermittent rise and fall of the chest observed with each ventilation</td></tr><tr><td></td><td>return and maintenance of oxygenation.</td></tr><tr><td></td><td>exhaled CO2 detection (colorimetric detector or capnography)</td></tr><tr><td colspan=\"2\">The resuscitation is unsuccessful and the child is pronounced deceased.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Talk to the child’s parents and explain the child has died</td></tr><tr><td></td><td>Answer any questions parents may have</td></tr><tr><td></td><td>Debrief resus staff on medical aspects of resuscitation</td></tr><tr><td></td><td>Wellbeing check on for medical and nursing staff</td></tr><tr><td></td><td>Documentation in notes</td></tr><tr><td></td><td>Coroner’s referral (including police/SIDS death procedures/not removing any</td></tr><tr><td colspan=\"2\">equipment from body)</td></tr><tr><td></td><td>Social worker / chaplain / support for parents</td></tr><tr><td colspan=\"2\">Phoning child’s GP (debatable)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 24-year-old woman presents to your rural base hospital ED in the early stages of premature labour. She is a primigravida and has had no antenatal care to date. She is uncertain of the gestational age - she thinks she is “about 5 months”.","parts":[{"id":"a","label":"Part A","prompt":"Outline the pharmacological management of preterm labour - providing drug name(s), doses, and rationale (6 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) other management priorities (other than the pharmacotherapy already provided) (4 marks)"},{"id":"c","label":"Part C","prompt":"Discuss the gestational age cut-offs that inform decisions to resuscitate a premature neonate (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Antenatal corticosteroids – betamethasone 12.4mg IMI for foetal lung maturation</td></tr><tr><td></td><td>Antenatal MgSO4 4g for neonatal neuro protection</td></tr><tr><td></td><td>Tocolysis – nifedipine 20mg PO – repeat if ongoing at 20 minutes (x 2). Other</td></tr><tr><td colspan=\"2\">tocolytics e.g. salbutamol considered only if nifedipine contraindicated</td></tr><tr><td></td><td>Antibiotics – intrapartum GBS prophylaxis (IV benpen 1.8g q4h). If chorioamnionitis</td></tr><tr><td colspan=\"2\">suspected  (fever, tenderness, discharge)  amp/gent/metronidazole</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Set-up team/equipment/drugs for delivery, neonatal resus</td></tr><tr><td></td><td>Call for help – O&amp;G, paeds (if available – note rural setting)</td></tr><tr><td></td><td>Early activation of neonatal transport service (“NETS” or equivalent)</td></tr><tr><td></td><td>Early consideration of in-utero transfer to tertiary paeds centre</td></tr><tr><td></td><td>Urgent need to establish gestational age (formal US)</td></tr><tr><td colspan=\"2\">The gestational age at which the likelihood of ex-utero foetal viability warrants resuscitation</td></tr><tr><td colspan=\"2\">is controversial (the “threshold of viability”).</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Discuss the gestational age cut-offs that inform decisions to resuscitate a</td></tr><tr><td colspan=\"2\">premature neonate (3 marks)</td></tr><tr><td></td><td>Controversial. Varies from jurisdiction to jurisdiction. Survival dependent on highly</td></tr><tr><td colspan=\"2\">advanced health care system. Factors other than gestation are important – IUGR,</td></tr><tr><td colspan=\"2\">antenatal detection of congenital anomalies, wishes of parents</td></tr><tr><td></td><td>Generally (Australia/NZ)</td></tr><tr><td>o</td><td>Less than 22 weeks – do not attempt/offer resuscitation</td></tr><tr><td>o</td><td>More than 24 weeks – resuscitate</td></tr><tr><td>o</td><td>Between 22-24 weeks – need multidisciplinary team decision, parental input</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"You are a member of a retrieval team tasked by helicopter to retrieve a 25-year-old from a small peripheral country hospital to the major trauma centre. The pilot estimates a flight time of 1 1⁄2 hours. The patient has been involved in an MBA. He has bruising and abrasions to the right side of his chest, pain and bruising to his right upper quadrant, and a deformed left thigh with an open femoral fracture.\nHis observations:\n\nRR 22\n\nSats 96% on 2l via nasal cannula\n\nHR 90\n\nBP 146/77\n\nGCS 14/15 - E4M6V4","parts":[{"id":"a","label":"Part A","prompt":"List four (4) methods to reduce the risk of ongoing blood loss in this patient. (4 marks)"},{"id":"b","label":"Part B","prompt":"On your arrival you perform an eFAST examination during which you find a loss of lung sliding on the right side of the chest. List two (2) absolute indications for chest drain insertion prior to transfer for this patient. (2 marks)"},{"id":"c","label":"Part C","prompt":"List four (4) other factors you would consider when deciding whether to insert a chest drain. (4 marks)"},{"id":"d","label":"Part D","prompt":"List one (1) advantage and one (1) disadvantage of each of the following patient transport methods. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">marks)</td></tr><tr><td></td><td><em><strong>Direct pressure to femoral wound </strong></em></td></tr><tr><td></td><td><em><strong> Femoral splint</strong></em></td></tr><tr><td></td><td><em><strong> Pelvic splint </strong></em></td></tr><tr><td></td><td><em><strong>Keep pt warm </strong></em></td></tr><tr><td></td><td><em><strong>TXA </strong></em></td></tr><tr><td></td><td><em>Avoid acidosis (maintain perfusion etc) </em></td></tr><tr><td></td><td><em> Avoid Hypocalcaemia </em></td></tr><tr><td colspan=\"2\">On your arrival you perform an eFAST examination during which you find a loss of lung</td></tr><tr><td colspan=\"2\">sliding on the right side of the chest.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Hypotension (tension pneumothorax) </em></div><div class=\"answer-line\"></div><div class=\"answer-line\"><em>Ventilatory compromise </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">List four (4) <strong>other </strong>factors you would consider when deciding whether to insert a</td></tr><tr><td colspan=\"2\">chest drain. (4 marks)</td></tr><tr><td></td><td><em>Distance in flight </em></td></tr><tr><td></td><td><em>Altitude of flight </em></td></tr><tr><td></td><td><em>Positioning in aircraft i.e. if limited access to pt chest in flight </em></td></tr><tr><td></td><td><em>Clinical course so far e.g. worsening clinical picture risk of deterioration </em></td></tr><tr><td></td><td><em>Need for positive pressure ventilation </em></td></tr><tr><td colspan=\"2\"><em>Pt habitus i.e. if large may be a challenging procedure in flight</em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Fixed Wing</td><td></td><td><em>Fast (est) for long </em>  <em>Need to land at an </em></td></tr><tr><td><em>distances</em></td><td><em>airport therefore </em></td><td></td></tr><tr><td><em>road leg required at </em></td><td></td><td></td></tr><tr><td></td><td><em>Able to fly in poorer </em></td><td><em>both ends</em></td></tr><tr><td><em>weather than helo </em></td><td></td><td><em>Often limited access </em></td></tr><tr><td><em>to patients due to pt </em></td><td></td><td></td></tr><tr><td><em>position </em></td><td></td><td></td></tr><tr><td>Rotary Wing</td><td></td><td><em>Can land at scene </em>  <em>Limited by weather </em></td></tr><tr><td><em>and also at hospital </em></td><td></td><td><em>Difficult </em></td></tr><tr><td><em>environment to work </em></td><td></td><td></td></tr><tr><td></td><td><em>Fly in a straight line </em></td><td><em>in during flight </em></td></tr><tr><td></td><td><em>Limited range may </em></td><td></td></tr><tr><td></td><td><em>Traffic less of an </em></td><td><em>require refuelling on </em></td></tr><tr><td><em>issue </em></td><td><em>longer taskings </em></td><td></td></tr><tr><td></td><td><em>Communication </em></td><td></td></tr><tr><td><em>limited to headsets </em></td><td></td><td></td></tr><tr><td><em>as loud </em></td><td></td><td></td></tr><tr><td>Road Ambulance</td><td></td><td><em>Cheap </em>  <em>Slow </em></td></tr><tr><td></td><td><em>Can pull over and </em></td><td></td></tr><tr><td><em>treat pt at side of </em></td><td></td><td></td></tr><tr><td><em>road. Generally </em></td><td></td><td></td></tr><tr><td><em>better environment </em></td><td></td><td></td></tr><tr><td><em>to work clinically in </em></td><td></td><td></td></tr><tr><td></td><td><em>Weather less of an </em></td><td></td></tr><tr><td><em>issue </em></td><td></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 45-year-old man presents with sharp left-sided chest pain over a few days. It improves when he sits up. He is normally well but smokes cigarettes.\nHis 12-lead ECG is shown below:","parts":[{"id":"a","label":"Part A","prompt":"Describe this ECG and note which findings make STEMI more likely than pericarditis as an explanation for the ST-segment elevation (4 marks)"},{"id":"b","label":"Part B","prompt":"A 65-year-old woman presents with sharp left-sided chest pain over a few days. It improves when she sits up. She is normally well but smokes cigarettes. Describe this ECG and note which findings (positive or negative) make pericarditis more likely than STEMI as an explanation for the ST-segment elevation (5 marks)"},{"id":"c","label":"Part C","prompt":"Other than STEMI and pericarditis, list five (5) other causes of ST segment elevation (5 marks)"}],"propPages":["asset:img123aa75a4266da1721","asset:img2deff3fd93fba3640b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Sinus tachycardia. PR depression II, aVF +/- V5 V6. Widespread ST segment elevation.</div><div class=\"answer-line\">The STE in III is greater than the STE in II which suggests STEMI. The ST segments are</div><div class=\"answer-line\">horizontal in V3 and V4 which suggests STEMI (pericarditis causes concave up STE)</div><div class=\"answer-line\">A 65-year-old woman presents with sharp left-sided chest pain over a few days. It improves</div><div class=\"answer-line\">when she sits up. She is normally well but smokes cigarettes.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Sinus tachy, widespread STE inf/septal/lateral. Widespread PR depression inf / V3-5. This is</td></tr><tr><td colspan=\"2\">most consistent with pericarditis.</td></tr><tr><td colspan=\"2\">Factors that would suggest STEMI (but which are absent here):</td></tr><tr><td></td><td>ST depression (other than in aVR and VI) – suggests STEMI</td></tr><tr><td></td><td>STE in III &gt; than in II -  suggests STEMI</td></tr><tr><td></td><td>Horizontal or convex-up – suggests STEMI</td></tr><tr><td colspan=\"2\">In this ECG these factors are absent and, in this clinical context, this is most consistent with</td></tr><tr><td colspan=\"2\">pericarditis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Other than STEMI and pericarditis</strong>, list five (5) other causes of ST segment elevation</td></tr><tr><td colspan=\"2\">(5 marks)</td></tr><tr><td></td><td>BER</td></tr><tr><td></td><td>LBBB</td></tr><tr><td></td><td>LVH</td></tr><tr><td></td><td>Ventricular aneurysm</td></tr><tr><td></td><td>Brugada syndrome</td></tr><tr><td></td><td>Paced rhythm</td></tr><tr><td></td><td>Raised ICP</td></tr><tr><td colspan=\"2\">Takotsubo cardiomyopathy</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A dentist has referred a patient to your ED who he thinks may have Ludwig’s angina.","parts":[{"id":"a","label":"Part A","prompt":"What is Ludwig’s angina? (2 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) possible examination findings in a patient with Ludwig’s angina (4 marks)"},{"id":"c","label":"Part C","prompt":"The patient deteriorates and you decide you will need to intubate. You predict he will be a difficult intubation. List four (4) factors which would lead you to predict a patient may be difficult to intubate (4 marks)"},{"id":"d","label":"Part D","prompt":"Briefly discuss the limitations of physical examination tests for the detection of difficult airway management (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>A rapidly progressive gangrenous cellulitis of the submandibular space / soft tissues of the </em></div><div class=\"answer-line\"><em>neck and floor of the mouth, with risk of life-threatening airway compromise. Typically </em></div><div class=\"answer-line\"><em>caused by strep. Pyogenes, staph aureus, fusobacterium spp</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Tongue elevated and displaced anteriorly, inability to protrude tongue</em></div><div class=\"answer-line\"><em>Mouth or throat pain</em></div><div class=\"answer-line\"><em>Stridor</em></div><div class=\"answer-line\"><em>Dysphonia / ‘hot potato’ voice</em></div><div class=\"answer-line\"><em>Bilateral “brawny”/tense submandibular swelling / Bull neck appearance</em></div><div class=\"answer-line\"><em>Dysphagia / Inability to swallow saliva</em></div><div class=\"answer-line\"><em>Neural defects (CN involvement); Horner’s syndrome</em></div><div class=\"answer-line\"><em>Trismus</em></div><div class=\"answer-line\"><em>Torticollis</em></div><div class=\"answer-line\"><em>Erythema/Fluctuance over neck</em></div><div class=\"answer-line\"><em>Tenderness over the neck and throat</em></div><div class=\"answer-line\"><em>Submandibular ‘woody’ induration, crepitus or tenderness</em></div><div class=\"answer-line\"><em>Tachycardia / Fever</em></div><div class=\"answer-line\"><em>Tripod position and respiratory distress</em></div><div class=\"answer-line\">The patient deteriorates and you decide you will need to intubate. You predict he will be a</div><div class=\"answer-line\">difficult intubation.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List four (4) factors which would lead you to predict a patient may be difficult to</div><div class=\"answer-line\">intubate (4 marks)</div><div class=\"answer-line\">3, 3, 2 assessment – incisor distance (mouth opening), hyoid-mental distance, thyromental</div><div class=\"answer-line\">distance</div><div class=\"answer-line\">Modified Mallampati score – highest sensitivity for difficult intubation in 2018 cochrane</div><div class=\"answer-line\">review (though still only 51%. Specificity higher at 87%. Basically pretty rubbish</div><div class=\"answer-line\">Upper lip bite test – highest sensitivity for difficult laryngoscopy in above review</div><div class=\"answer-line\">Obstruction / obesity</div><div class=\"answer-line\">Neck mobility – c-spine collar etc</div><div class=\"answer-line\">Any other reasonable</div><div class=\"answer-line\">full#:~:text=The%20modified%20Mallampati%20test%20had%20the%20highest%20sensitivi</div><div class=\"answer-line\">ty%20of%20all,for%20the%20modified%20Mallampati%20test.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">All are designed as screening tests.</div><div class=\"answer-line\">Screening tests are supposed to have high sensitivity.</div><div class=\"answer-line\">All the bedside airway examination tests have terrible sensitivity.</div><div class=\"answer-line\">Higher specificity, though still not great – see above Cochrane review link</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 23-year-old female presents with lower abdominal discomfort and some PV bleeding. Her LMP was 5 weeks ago and her urine BHCG is positive","parts":[{"id":"a","label":"Part A","prompt":"List six (6) factors in the history that would predispose to ectopic pregnancy (6 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) examination features that make ectopic rather than intrauterine pregnancy more likely. (4 marks)"},{"id":"c","label":"Part C","prompt":"Outline your immediate management (4 marks)"},{"id":"d","label":"Part D","prompt":"List three (3) reasons why she might be bradycardic. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\"><em>From emedicine and oxford handbook of EM:</em></div><div class=\"answer-line\"><em>Now occurs in 2% of pregnancies, typically present at 5 to 14 weeks. In theory, anything that </em></div><div class=\"answer-line\"><em>hampers the migration of the embryo to the endometrial cavity could predispose women to </em></div><div class=\"answer-line\"><em>ectopic gestation. however, most patients presenting with an ectopic pregnancy have no </em></div><div class=\"answer-line\"><em>identifiable risk factor. Factors that have been linked…</em></div><div class=\"answer-line\"><em><strong>Tubal surgery or tubal ligation</strong></em><em> (35 to 50% after ligation)</em></div><div class=\"answer-line\"><em><strong>History of ectopic pregnancy</strong></em><em> (10 to 25%)</em></div><div class=\"answer-line\"><em><strong>Pelvic inflammatory disease</strong></em><em> (4 fold)</em></div><div class=\"answer-line\"><em><strong>Age.</strong></em><em> Highest rate in age 35 to 44 (4 fold compared to under 25s)</em></div><div class=\"answer-line\"><em><strong>Use of fertility drugs or assisted reproduction</strong></em><em> (IVF ectopic rate 4.5%, IVF and GIFT 1% risk of </em></div><div class=\"answer-line\"><em>heterotopic pregnancy compared to 1 in 30,000 if spontaneous)</em></div><div class=\"answer-line\"><em><strong>IUD</strong></em><em> (3-4%)</em></div><div class=\"answer-line\"><em><strong>Smoking</strong></em></div><div class=\"answer-line\"><em>Also… Progesterone only pill, endometriosis, pelvic / abdominal surgery and adhesions, T-</em></div><div class=\"answer-line\"><em>shaped uterus, ovarian / uterine cysts and tumours</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>emedicine and NHS clinical knowledge summary (NICE): </em></div><div class=\"answer-line\"><em>Abdominal tenderness, Cervical motion tenderness, Adnexal tenderness, adnexal mass, </em></div><div class=\"answer-line\"><em>haemodynamic compromise</em></div><div class=\"answer-line\">An ultrasound confirms intra-uterine pregnancy. On return she becomes unwell – systolic 70</div><div class=\"answer-line\">and bradycardic. She is placed in resus and is on a monitor.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>IV access x 2 and crystalloid bolus</em></div><div class=\"answer-line\"><em>Speculum exam to see and remove clot/products from cervical os</em></div><div class=\"answer-line\"><em>Atropine if shock or syncope persists / inotropes</em></div><div class=\"answer-line\"><em>VBG – replace Hb if necessary</em></div><div class=\"answer-line\"><em>O&amp;G input may be required if heavy PV bleed / clots</em></div><div class=\"answer-line\"><em>(remember later to request rhesus status, and give anti-D if mum negative)</em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em>Blood or products in os causing vagal stimulus</em></div><div class=\"answer-line\"><em>Intra peritoneal or adnexal bleed causing vagal stimulus</em></div><div class=\"answer-line\"><em>Peri-arrest arrhythmia in uncompensated shock / haemorrhagic</em></div><div class=\"answer-line\"><em>Vasovagal response to pain</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 36-year-old male presents with 1 day of “blood stained” urine, generalised myalgia and tightness across his upper chest. He has a history of GORD but is not medicated. He has no other significant past medical history. He had a heavy gym session the day prior to noticing his urinary changes.","parts":[{"id":"a","label":"Part A","prompt":"List six (6) other clinical features you would specifically ask about when taking a history from this patient (6 marks)"},{"id":"b","label":"Part B","prompt":"His vital signs are: BP 130/78, HR 75, sats 98% RA, T 36.6.\nState the diagnosis and describe your initial management (4 marks)"},{"id":"c","label":"Part C","prompt":"Other than exertion or trauma, list four (4) other causes of this condition (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Urea</td><td>* H 8.5 mmol/L</td><td>would specifically ask about when taking</td></tr><tr><td colspan=\"3\">a history from this patient (6 marks)</td></tr><tr><td>Creat</td><td>* H 135 umol/L</td><td></td></tr><tr><td></td><td>Flank pain</td><td></td></tr><tr><td></td><td>Fever</td><td></td></tr><tr><td></td><td>lower urinary tract symptoms</td><td></td></tr><tr><td>eGFR</td><td>* 59 mL/min/1.73m2</td><td></td></tr><tr><td></td><td>Infective symptoms in preceding days</td><td></td></tr><tr><td>Bili</td><td>6 umol/L</td><td></td></tr><tr><td></td><td>hydration following gym session and</td><td></td></tr><tr><td colspan=\"3\">intensity compared with usual work out</td></tr><tr><td>ALP</td><td>93 U/L</td><td></td></tr><tr><td></td><td>dyspnoea</td><td></td></tr><tr><td>GGT</td><td>50 U/L</td><td></td></tr><tr><td></td><td>Chest tightness: site, radiation,</td><td></td></tr><tr><td colspan=\"3\">association with movement</td></tr><tr><td>ALT</td><td>C 887 U/L</td><td></td></tr><tr><td></td><td>risk factors for CV disease</td><td></td></tr><tr><td>AST</td><td>H 2,820 U/L</td><td></td></tr><tr><td></td><td>Drug use / social history</td><td></td></tr><tr><td></td><td>Any other reasonable – needs to be</td><td></td></tr><tr><td>CK</td><td>H 268,720 U/L</td><td></td></tr><tr><td colspan=\"3\">specific to DDx</td></tr><tr><td>Trop</td><td>* H 21 ng/L</td><td></td></tr><tr><td colspan=\"3\">His vital signs are: BP 130/78, HR 75, sats 98%</td></tr><tr><td colspan=\"3\">RA, T 36.6.</td></tr><tr><td colspan=\"3\">UA shows mod blood and protein. Neg nitrites and leukocyte esterase.</td></tr><tr><td colspan=\"3\">Blood results are shown below:</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Severe rhabdomyolysis with secondary renal impairment.</div><div class=\"answer-line\">N/sal initially 500ml/hr: aim for high U.O around 200ml/hr.</div><div class=\"answer-line\">Analgesia for muscle pain (avoid NSAIDs)</div><div class=\"answer-line\">Consider alkaline diuresis if not improving with saline</div><div class=\"answer-line\">Repeat EUC’s in 6-12 hrs following hydration</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- Drugs (statins, alcohol, cocaine, methamphetamines, serotonin syndrome, NMS, carbon</div><div class=\"answer-line\">monoxide)</div><div class=\"answer-line\">- Metabolic (esp hypokalaemia and hypophosphataemia)</div><div class=\"answer-line\">- Toxins (snakes, mushrooms)</div><div class=\"answer-line\">- Infections (viral - influenza, coxsackie, adenovirus, EBV, CMV, HIV; bacterial; malaria</div><div class=\"answer-line\">- Vascular (vasculitis, ischaemic, sickle-cell)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false,"investigationTables":[{"id":"investigation-1","title":"Blood results","headers":["Test","Result"],"rows":[["Sodium","138"],["Potassium","* 4.4 mmol/L"],["chloride","* 96 mmol/L"],["HCO3","* 27 mmol/L"],["Urea","* H 8.5 mmol/L"],["Creat","* H 135 umol/L"],["eGFR","* 59 mL/min/1.73m2"],["Bili","6 umol/L"],["ALP","93 U/L"],["GGT","50 U/L"],["ALT","C 887 U/L"],["AST","H 2,820 U/L"],["CK","H 268,720 U/L"],["Trop","* H 21 ng/L"]]}]},{"number":25,"title":"","stemText":"A 47-year-old male is brought into your emergency department following deliberate self-poisoning by ingestion of an organophosphate insecticide.","parts":[{"id":"a","label":"Part A","prompt":"List six (6) possible clinical features that would prompt the use of antidote treatment for this patient (6 marks)."},{"id":"b","label":"Part B","prompt":"List two (2) relative contraindications for the use of atropine (2 marks)."},{"id":"c","label":"Part C","prompt":"Complete the table with details of administration of atropine for this patient (4 marks)."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Miosis</td></tr><tr><td>-</td><td>Excessive sweating/secretions</td></tr><tr><td>-</td><td>Poor air entry</td></tr><tr><td>-</td><td>Wheeze</td></tr><tr><td>-</td><td>Cough</td></tr><tr><td>-</td><td>Bradycardia</td></tr><tr><td>-</td><td>Hypotension</td></tr><tr><td>-</td><td>Respiratory distress</td></tr><tr><td colspan=\"2\">Based on your patient assessment, you decide that antidote treatment with atropine will be</td></tr><tr><td colspan=\"2\">required.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Closed angle glaucoma</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Obstructive disease of gastrointestinal tract</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Obstructive uropathy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Complete the table with details of administration of atropine for this patient (4</td></tr><tr><td colspan=\"2\">marks).</td></tr><tr><td colspan=\"2\">Initial dose</td></tr><tr><td colspan=\"2\">Frequency</td></tr><tr><td colspan=\"2\">Ongoing dose regime</td></tr><tr><td colspan=\"2\">Endpoint</td></tr><tr><td colspan=\"2\">Answer:</td></tr><tr><td>Initial dose</td><td>1.2mg</td></tr><tr><td>Frequency</td><td>Every 2-3 minutes*</td></tr><tr><td>Ongoing dose regime</td><td>Double dose each time</td></tr><tr><td>Endpoint+</td><td>Drying of respiratory secretions (<em>Tox Handbook)</em></td></tr><tr><td colspan=\"2\">Clear chest, HR&gt;80 and sBP &gt;80mmHg (<em>Tintinalli)</em></td></tr><tr><td colspan=\"2\">*  <em>Toxicology Handbook</em> specifies every 2-3mins, <em>Tintinalli</em> recommends every 5mins</td></tr><tr><td colspan=\"2\">+ Heart rate is not a useful end point as tachycardia may persist due to nicotinic effects or</td></tr><tr><td colspan=\"2\">respiratory distress. (<em>Toxicology Handbook ePUB3) </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 53-year-old male presents to your rural ED feeling unwell. He has recently been bushwalking and states he noticed this painless rash develop on his leg over the last 2 days (see picture below)","parts":[{"id":"a","label":"Part A","prompt":"Describe the findings in the picture above and state the most likely diagnosis (2 marks)"},{"id":"b","label":"Part B","prompt":"Other than the skin findings seen above, list six (6) clinical features of this condition (6 marks)"},{"id":"c","label":"Part C","prompt":"Outline the treatment for this condition (2 marks)"},{"id":"d","label":"Part D","prompt":"List two (2) complications of this condition (2 marks)"}],"propPages":["asset:img2f81b1e5dd60bd1f9f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\"><strong>Central eschar</strong> with surrounding erythema and some desquamation at the margins</div><div class=\"answer-line\">Rickettsial infection – scrub typhus or spotted fever - 65% have a visible eschar at the bite</div><div class=\"answer-line\">site</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">(From Dunn)</div><div class=\"answer-line\">Spotted fever:</div><div class=\"answer-line\">incubation period 3-10 days</div><div class=\"answer-line\">•fevers, chills</div><div class=\"answer-line\">•restlessness, insomnia, irritability</div><div class=\"answer-line\">•delirium, coma, seizures</div><div class=\"answer-line\">•rash</div><div class=\"answer-line\">-may be macular through maculopapular to petechial</div><div class=\"answer-line\">-initially on wrists and ankles</div><div class=\"answer-line\">-spreads to arm, legs and trunk</div><div class=\"answer-line\">•regional lymphadenopathy</div><div class=\"answer-line\">•arthralgia</div><div class=\"answer-line\">•conjunctivitis</div><div class=\"answer-line\">•pharyngitis</div><div class=\"answer-line\">Scrub typhus:</div><div class=\"answer-line\">•1-3 week incubation period</div><div class=\"answer-line\">•malaise</div><div class=\"answer-line\">•headache</div><div class=\"answer-line\">•backache</div><div class=\"answer-line\">•rigors</div><div class=\"answer-line\">•black eschar at bite site</div><div class=\"answer-line\">-painless</div><div class=\"answer-line\">•lymphadenopathy</div><div class=\"answer-line\">•short-lived macular rash</div><div class=\"answer-line\">•altered mental state</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">(From ETG)</td></tr><tr><td>-</td><td>doxycycline 100 mg (child: 2.2 mg/kg up to 100 mg) orally, 12-hourly for 7 days</td></tr><tr><td colspan=\"2\">OR</td></tr><tr><td>-</td><td>azithromycin 500 mg (child: 10 mg/kg up to 500 mg) orally on the first day, then 250</td></tr><tr><td colspan=\"2\">mg (child: 5 mg/kg up to 250 mg) orally, daily for a further 4 days.</td></tr><tr><td>-</td><td>Supportive care</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">•pneumonia</div><div class=\"answer-line\">•encephalitis</div><div class=\"answer-line\">•cardiac failure</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"The Director of your tertiary hospital ED has asked for input from the FACEM group about how to minimise the effect of access block on the ED.","parts":[{"id":"a","label":"Part A","prompt":"Define access block (3 marks)"},{"id":"b","label":"Part B","prompt":"Outline why this is the case (2 marks)"},{"id":"c","label":"Part C","prompt":"Define ambulance ramping/off-stretcher delay (3 marks)"},{"id":"d","label":"Part D","prompt":"List four (4) adverse outcomes of ambulance ramping/off-stretcher delay (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">The situation where <em>patients who have been admitted</em> and need a hospital bed are<em> delayed </em></div><div class=\"answer-line\"><em>from leaving the emergency department (ED) </em>for more than eight hours because of a <em>lack of </em></div><div class=\"answer-line\"><em>inpatient bed capacity</em>. This includes patients who were planned for an admission but were</div><div class=\"answer-line\">discharged from the ED without reaching an inpatient bed, or transferred to another</div><div class=\"answer-line\">hospital for admission, or who died in the ED.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ACEM defines ‘overcrowding’ as ‘the situation where ED function is impeded because <em>the </em></div><div class=\"answer-line\"><em>number of patients exceeds the physical and/or staffing capacity of the ED’</em>. It includes</div><div class=\"answer-line\">patients <em>undergoing triage, waiting to be seen, undergoing assessment and treatment, or </em></div><div class=\"answer-line\"><em>waiting for departure</em> from the ED</div><div class=\"answer-line\">“Pre-ED” interventions to reduce patient presentations – e.g public messaging campaigns</div><div class=\"answer-line\">like “Keep emergency departments for emergencies” – have little impact on access block.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">‘Pre-ED’ interventions that might reduce the volume of presentations to an ED are much</div><div class=\"answer-line\">more likely to apply to patients who do not require admission – e.g. “triage away to GP”.</div><div class=\"answer-line\">While these interventions might help to alleviate overcrowding, they cannot be expected to</div><div class=\"answer-line\">have much effect on access block.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Ambulance ramping/off-stretcher delay occurs when paramedics are <em>unable to complete </em></div><div class=\"answer-line\"><em>transfer of clinical care</em> of their patient to the hospital ED within a clinically appropriate</div><div class=\"answer-line\">timeframe, specifically due to <em>lack of an appropriate, staffed clinical space</em> in the hospital or</div><div class=\"answer-line\">the ED. This is a direct consequence of access block.</div><div class=\"answer-line\">e. List four (4) adverse outcomes of ambulance ramping/off-stretcher delay (4 marks)</div><div class=\"answer-line\">• Delayed access to timely pre-hospital assessment and care due to fewer ambulance crews</div><div class=\"answer-line\">being available. • Delayed access to timely ED services and definitive specialist assessment</div><div class=\"answer-line\">and care. • Financial implications for ambulance services and hospitals. • Adverse publicity</div><div class=\"answer-line\">leading to poor staff morale and negative public perceptions of the health system. •</div><div class=\"answer-line\">Increased stress and interpersonal conflict between patients, paramedics, ED, and hospital</div><div class=\"answer-line\">staff, including exacerbation of occupational violence. • Extended time per assessment in</div><div class=\"answer-line\">the ED relating to data sharing requirements for patients diverted out of area. • Increased</div><div class=\"answer-line\">repatriation costs for patients diverted out of area. • More complexity of care for patients</div><div class=\"answer-line\">who transported beyond usual care provision.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
